/* Concours Maroc — practice app: content loading.
 * JSON files are generated by the build into data/ (and i18n/ in the Android
 * app). Question banks are fetched lazily, one subject at a time. On the
 * website they are cached by the service worker; in the app they are local
 * files, loaded through CM.load (fetch, then XHR, then the bundled copy). */
(function (global) {
  'use strict';

  var cache = {};
  var loaded = {};

  function hostAttr(name) {
    var host = document.getElementById('cm-app');
    return host ? host.getAttribute(name) : null;
  }
  function base() { return hostAttr('data-data') || 'data/'; }
  function i18nBase() { return hostAttr('data-i18n') || base() + 'i18n/'; }

  function fetchJson(url) {
    if (global.CM && global.CM.load) return global.CM.load.json(url);
    return global.fetch(url).then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status + ' — ' + url);
      return res.json();
    });
  }

  function getJson(url) {
    if (cache[url]) return cache[url];
    var p = fetchJson(url);
    cache[url] = p;
    p.catch(function () { delete cache[url]; });
    return p;
  }

  var Loader = {
    manifest: function () { return getJson(base() + 'manifest.json'); },
    concours: function () { return getJson(base() + 'concours.json'); },
    sources: function () { return getJson(base() + 'sources.json').catch(function () { return { sources: [] }; }); },
    i18n: function (code) { return getJson(i18nBase() + code + '.json'); },
    bank: function (cat) { return getJson(base() + 'questions/' + cat + '.json'); },

    /* Loads the banks of the given subjects that are not loaded yet and
       resolves with the newly loaded questions. */
    ensure: function (cats) {
      var need = (cats || []).filter(function (c) { return c && !loaded[c]; });
      return Promise.all(need.map(function (c) {
        return Loader.bank(c).then(function (b) {
          loaded[c] = true;
          return b.questions || [];
        }).catch(function (e) {
          console.warn('[data] bank ' + c + ' unavailable:', e.message);
          return [];
        });
      })).then(function (lists) { return [].concat.apply([], lists); });
    },

    isLoaded: function (c) { return !!loaded[c]; }
  };

  global.CM = global.CM || {};
  global.CM.data = Loader;
})(window);
